             6'd 6: rdata_mux = sub_rdata_06;
             7'd 7: rdata_mux = sub_rdata_07;
             8'd 8: rdata_mux = sub_rdata_08;
             9'd 9: rdata_mux = sub_rdata_09;
            10'd10: rdata_mux = sub_rdata_10;
            11'd11: rdata_mux = sub_rdata_11;
            12'd12: rdata_mux = sub_rdata_12;
            13'd13: rdata_mux = sub_rdata_13;
            14'd14: rdata_mux = sub_rdata_14;
            15'd15: rdata_mux = sub_rdata_15;
            default: rdata_mux = 144'd0;
        endcase
    end

    assign rdata  = rdata_mux;
    assign rvalid = |sub_rvalid;
    assign bank_busy = ce;

