            15'd15: rdata_mux = sub_rdata_15;
            default: rdata_mux = 144'd0;
        endcase
    end

    assign rdata  = rdata_mux;
    assign rvalid = |sub_rvalid;
    assign bank_busy = ce;

endmodule

