    reg [4:0] bank_sel_q, bank_sel_q2;
    always @(posedge clk or posedge rst) begin
        if (rst) begin bank_sel_q <= 5'd0; bank_sel_q2 <= 5'd0; end
        else     begin bank_sel_q <= bank_sel; bank_sel_q2 <= bank_sel_q; end
